#include <bits/stdc++.h>
#include <atcoder/dsu>
#include <atcoder/modint>

using namespace std;

using mint = atcoder::modint998244353;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> u(m), v(m);
    vector<mint> cost(m);
    for (int i = 0; i < m; i++) {
        cin >> u[i] >> v[i];
        --u[i], --v[i];
        cost[i] = (i ? cost[i - 1] * 2 : 2);
    }

    atcoder::dsu uf(n);
    mint ans = 0;
    int cnt = n;
    for (int i = m - 1; i >= 0; i--) {
        if (!uf.same(u[i], v[i])) {
            if (cnt > 2) {
                uf.merge(u[i], v[i]);
                --cnt;
            } else {
                ans += cost[i];
            }
        }
    }
    cout << ans.val() << endl;
}
